[247614] = {
["BroadcastText"] = {
["enUS"] = {
["It over?"] = true,
["Smell that rot? Toxic twins must be looking for fight!"] = true,
["Not over! Not over!"] = true,
["Fungi and mycelia, here come the big shroom!"] = true,
["The feral fungus! The toxic twister! The champion champignon!"] = true,
["GYROSPORE!"] = true,
["You fight, you dodge spores, but you ready for the big time? Plant challenge banner and see!"] = true,
["Stupid glowheads wanted fight. Now they dead!"] = true,
["Uh-oh, dead fighters go rotten. Pick up mold before it go bad!"] = true,
["Get bomb spores! They turn thornmaws into mulch."] = true,
["They charging barricades!"] = true,
